import * as React from "react";

export type RockIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function RockIcon({ size = 20, ...props }: RockIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M5 9.5 8.5 5h7L20 10l-2.5 8h-10L5 9.5Z"/>
    </svg>
  );
}
